# ================================================================ 4.3.1–4.3.2
L(
    id="az305-migration-planning", title="Plan migrations with the Cloud Adoption Framework", objectives=["AZ305-4.3.1", "AZ305-4.3.2"], minutes=40,
    objective="Evaluate a migration approach that uses the Cloud Adoption Framework, and evaluate on-premises servers, data and applications for migration.",
    prereqs=[("Governance design", "AZ305-1.3.1", "az305-governance")],
    foundation=[
        "Big migrations fail when they start with servers instead of goals. The Cloud Adoption Framework (CAF) is Microsoft's step-by-step method.",
        "First agree why you are moving, then plan which apps go where, prepare a landing zone, and only then move workloads in waves.",
        "Azure Migrate discovers what you have, measures how it performs, maps dependencies and estimates Azure cost.",
    ],
    engineer=[
        "CAF methodologies: Strategy (motivations, business outcomes, business case), Plan (digital estate inventory and rationalisation, skills, adoption plan), Ready (Azure landing zones: identity, network topology, governance, management, security), Adopt (Migrate and Modernize/Innovate), plus Govern, Secure and Manage across the lifecycle. Migration waves group workloads by dependency and risk; start with low-risk workloads.",
        "Rationalisation (the Rs): retire, retain, rehost (lift and shift), replatform (minimal changes to use PaaS), refactor (code changes for cloud-native), rearchitect, rebuild, replace with SaaS.",
        "Assessment with Azure Migrate: agentless discovery of VMware, Hyper-V and physical servers through the Azure Migrate appliance (or CSV import), performance-based right-sizing, Azure readiness, cost estimates, business case (TCO comparison), dependency analysis (agentless or agent-based) to group servers that must move together, and assessments for SQL Server, web apps and AVS. Database assessments flag compatibility issues for SQL Database, Managed Instance or SQL on VMs.",
    ],
    anim=("az305-migrate-plan-sim", "Place activities in CAF phases and choose Azure Migrate for discovery and assessment."),
    example=("Exiting a datacenter in 18 months", [
        "Strategy: leadership agrees to exit the datacenter lease and cut run costs by 20%. Plan: Azure Migrate discovers 600 servers; dependency analysis groups them into 12 waves; each app gets a decision (rehost, replatform, replace, retire).",
        "Ready: the landing zone (management groups, hub network, policies) is deployed with Bicep before the first wave. Adopt: wave 1 rehosts low-risk internal apps.",
    ]),
    config=cfg(["Azure Migrate > Servers, databases and web apps > Discover: download the appliance or import a CSV.", "Azure Migrate > Assess: Azure VM, Azure SQL, web apps, AVS; Business case.", "Dependency analysis > Agentless."],
               cli="# Azure Migrate projects are usually created in the portal\naz resource create -g rg-migrate -n migrate-proj --resource-type Microsoft.Migrate/migrateProjects --properties '{}' -l westeurope",
               ps="# Az.Migrate module: New-AzMigrateProject is not required; create the project in the portal, then use Get-AzMigrateDiscoveredServer"),
    lab=lab("Place activities in CAF phases and choose the assessment approach.", [("migrate-plan", "CAF phase or tool")], ["Answer every case."], ["Strategy → Plan → Ready → Adopt", "Azure Migrate discovers, assesses and maps dependencies"], ["Moving servers before the landing zone exists", "Migrating without dependency analysis"]),
    troubleshooting=[("Migrated app breaks because a dependent server was left on-premises.", "No dependency analysis.", "Run dependency analysis and move dependent servers in the same wave."),
                     ("Azure cost is much higher than expected after rehosting.", "As-is sizing of over-provisioned servers.", "Use performance-based assessments and right-size.")],
    comparisons=[("Rehost vs replatform", "Rehost moves as-is to VMs; replatform makes small changes to use PaaS such as App Service or SQL MI."), ("Ready vs Adopt", "Ready prepares the landing zone; Adopt moves the workloads.")],
    misconceptions=[("Migration starts with moving servers.", "It starts with strategy, planning and a landing zone."), ("Assessments use the on-premises size.", "Performance-based sizing usually recommends smaller Azure sizes.")],
    decisions=["Follow CAF: strategy, plan, ready, adopt.", "Discover and assess with Azure Migrate, using performance data and dependency analysis.", "Move in waves, low risk first."],
    docs=[("Cloud Adoption Framework", CAF), ("Plan for cloud adoption", CAF + "plan/"), ("Azure landing zones", CAF + "ready/landing-zone/"), ("About Azure Migrate", MIG + "migrate-services-overview"), ("Dependency analysis", MIG + "concepts-dependency-visualization")],
    walk_=("Move to Azure in a planned, low-risk way: goals first, then plan, prepare, and move in waves.",
           ["CAF phases", "Rationalise each app: the Rs", "Discover and assess with Azure Migrate"],
           row(0, ("strat", "Strategy", "user", "why move?"), ("plan", "Plan", "service", "what, when"), ("ready", "Ready", "network", "landing zone"), ("adopt", "Adopt", "compute", "migrate"))
           + row(1, ("dc", "Datacenter", "compute", "600 servers"), ("appl", "Migrate appliance", "service", "agentless"), ("am", "Azure Migrate", "service", "assess + cost"))
           + row(2, ("deps", "Dependency map", "service"), ("waves", "Migration waves", "user")),
           [S("problem", "Problem", "600 servers and a lease ending", "Moving everything at once is risky and moving nothing is expensive. You need a method.", add=["dc"]),
            S("concept", "CAF", "Four steps before and during the move", "Strategy: why move? Plan: inventory and decide per app. Ready: build the landing zone. Adopt: migrate and modernise. Govern, Secure and Manage run throughout.", add=["strat", "plan", "ready", "adopt"], edges=[("strat", "plan"), ("plan", "ready"), ("ready", "adopt")], learn=[0]),
            S("concept", "Rationalise", "A decision for every app", "Retire what nobody uses, retain what must stay, rehost to move fast, replatform to use PaaS with small changes, refactor or rebuild for cloud-native, or replace with SaaS.", focus=["plan"], learn=[1]),
            S("technique", "Assess", "Azure Migrate does the counting", "An agentless appliance discovers servers and collects performance data. Assessments recommend Azure sizes and costs; dependency analysis shows which servers talk to each other, so they move in the same wave.", add=["appl", "am", "deps", "waves"], edges=[("dc", "appl"), ("appl", "am"), ("am", "deps"), ("deps", "waves")], learn=[2]),
            S("recap", "Recap", "Migration planning", "Goals, plan, landing zone, waves.", recap=["Strategy → Plan → Ready → Adopt (+ Govern, Secure, Manage)", "Retire, retain, rehost, replatform, refactor, replace", "Azure Migrate: discovery, performance sizing, dependencies, business case"])]),
)
qa("AZ305-4.3.1", 2, "scenario", "Before migrating any workload, the company must deploy management groups, a hub network, identity and policies. Which CAF methodology covers this?", [("Ready (Azure landing zones)", "Correct."), ("Strategy", "Motivations and outcomes."), ("Plan", "Inventory and rationalisation."), ("Adopt", "Moving workloads.")], "a", "Ready prepares the landing zone before adoption.", CAF + "ready/landing-zone/")
qa("AZ305-4.3.1", 2, "scenario", "Leadership must agree on business outcomes and build a business case for moving to Azure. Which CAF methodology?", [("Strategy", "Correct."), ("Ready", "Technical preparation."), ("Manage", "Operations."), ("Govern", "Policies and guardrails.")], "a", "Strategy defines motivations, outcomes and the business case.", CAF + "strategy/")
