qa("AZ305-4.3.2", 2, "scenario", "You must discover 400 VMware VMs without installing agents on them, collect performance data and get Azure size and cost recommendations. What do you use?", [("The Azure Migrate appliance with performance-based assessments", "Correct."), ("Azure Site Recovery", "Replication, not assessment."), ("Azure Advisor", "Only for resources already in Azure."), ("Manual spreadsheets", "Error-prone.")], "a", "The appliance discovers agentlessly and feeds assessments.", MIG + "migrate-services-overview")
qa("AZ305-4.3.2", 2, "scenario", "You must find which servers communicate with each other so they move in the same wave. What do you use?", [("Azure Migrate dependency analysis", "Correct."), ("Network Watcher", "For Azure networks."), ("Azure Monitor alerts", "Not on-premises dependency mapping."), ("Cost Management", "Costs only.")], "a", "Dependency analysis maps server-to-server connections.", MIG + "concepts-dependency-visualization")
qa("AZ305-4.3.2", 3, "scenario", "Before migrating, the business wants a comparison of on-premises costs versus Azure over 5 years. What do you use?", [("The Azure Migrate business case", "Correct."), ("A single VM assessment", "Doesn't compare total costs."), ("Azure pricing calculator only", "No on-premises comparison from discovery data."), ("Azure Advisor", "Not for on-premises.")], "a", "The business case compares on-premises and Azure TCO using discovered data.", MIG + "concepts-business-case-calculation")

# ================================================================ 4.3.3–4.3.5
L(
    id="az305-migration", title="Migrate workloads, databases and unstructured data", objectives=["AZ305-4.3.3", "AZ305-4.3.4", "AZ305-4.3.5"], minutes=45,
    objective="Recommend solutions for migrating workloads to IaaS and PaaS, migrating databases, and migrating unstructured data.",
    prereqs=[("Migration planning", "AZ305-4.3.1", "az305-migration-planning")],
    foundation=[
        "After planning, each workload moves with the right tool: Azure Migrate for servers and web apps, Database Migration Service for databases, and transfer tools for files.",
        "Online migrations keep the source running and sync until a short cutover. Offline migrations stop the source while copying — simpler, but longer downtime.",
    ],
    engineer=[
        "Workloads: Azure Migrate server migration (agentless for VMware and Hyper-V, agent-based for physical servers and other clouds) with test migrations and cutover; App Service migration for ASP.NET and Java web apps; Azure VMware Solution to move VMware estates without converting VMs; containerise apps to AKS or Container Apps when refactoring.",
        "Databases: choose the target first (SQL Database, SQL Managed Instance, SQL Server on VMs, PostgreSQL or MySQL flexible server, Cosmos DB); assess compatibility with Azure Migrate; migrate with Azure Database Migration Service (online for minimal downtime or offline), Managed Instance link (near-real-time replication to MI), log replay service, or backup and restore to SQL Server on VMs. Native tools for open-source databases (DMS, pg_dump, MySQL replication).",
        "Unstructured data: AzCopy (scriptable network copy), Azure Storage Mover (managed migration of file shares to Azure Files and Blob), Azure File Sync (keep local caches while centralising in Azure Files), Azure Data Box family (offline transfer for tens to hundreds of TB or more, when the network is slow), Data Factory for scheduled copies from other clouds or SaaS.",
    ],
    anim=("az305-migrate-sim", "Pick the strategy and tool for each server, app, database and data set."),
    example=("Wave 3: the finance system", [
        "The app servers are rehosted with Azure Migrate (agentless VMware) after a test migration; the web front end is replatformed to App Service.",
        "The 3 TB SQL Server database moves to SQL Managed Instance with an online DMS migration and a 10-minute cutover. 400 TB of scanned archives ship on Data Box; branch file shares move to Azure Files with Azure File Sync caching.",
    ]),
    config=cfg(["Azure Migrate > Migration and modernization > Replicate / Test migration / Migrate.", "Azure Database Migration Service > New migration (online/offline).", "Storage Mover > Projects > Job definitions; Data Box > Order."],
               cli="az datamigration sql-managed-instance create --source-location '{...}' --target-location '{...}' --migration-service <dms-id> \\\n  --scope <mi-id> -g rg-migrate --managed-instance-name sqlmi-fin --target-db-name findb\nazcopy copy 'C:\\shares\\docs' 'https://stfin.blob.core.windows.net/docs?<SAS>' --recursive",
               ps="New-AzDataMigrationToSqlManagedInstance -ResourceGroupName rg-migrate -ManagedInstanceName sqlmi-fin -TargetDbName findb -Kind SqlMI -Scope <mi-id> -MigrationService <dms-id>"),
    lab=lab("Pick the migration strategy and tool.", [("migrate-how", "migration approach or tool")], ["Answer every case."], ["Online DMS for minimal downtime", "Data Box when the network is the bottleneck"], ["Copying hundreds of TB over a slow link", "Offline database migration when downtime must be minutes"]),
    troubleshooting=[("Database cutover takes hours.", "Offline migration of a large database.", "Use an online migration (DMS or MI link) and cut over after sync."),
                     ("File copy will take months over the WAN.", "Network bandwidth too low for the volume.", "Use Azure Data Box for the bulk, then sync the delta online.")],
    comparisons=[("Online vs offline database migration", "Online syncs changes until cutover (minutes of downtime); offline stops writes during the copy."), ("Storage Mover vs File Sync", "Storage Mover migrates shares to Azure; File Sync keeps on-premises caches of Azure file shares.")],
    misconceptions=[("Lift and shift is always cheapest.", "Rehosting is fastest, but PaaS often costs less to run."), ("Data Box is only for petabytes.", "It suits tens of TB when bandwidth is limited too.")],
    decisions=["Rehost fast; replatform where effort is low and value high.", "Online database migration for production.", "Network copy when bandwidth allows; Data Box when it doesn't."],
    docs=[("Azure Migrate: migration and modernization", MIG + "migrate-services-overview"), ("Azure Database Migration Service", ML + "azure/dms/dms-overview"), ("Azure Storage Mover", ML + "azure/storage-mover/service-overview"), ("Azure Data Box", ML + "azure/databox/data-box-overview"), ("Azure File Sync", ML + "azure/storage/file-sync/file-sync-introduction")],
    walk_=("Move servers, apps, databases and files with the right tool and the least downtime.",
           ["Servers and apps: rehost or replatform", "Databases: online vs offline", "Files and big data: network or Data Box"],
           row(0, ("srv", "Servers", "compute"), ("am", "Azure Migrate", "service", "rehost"), ("vm", "Azure VMs", "compute"), ("aps", "App Service", "compute", "replatform"))
           + row(1, ("sql", "SQL Server", "database"), ("dms", "Database Migration Service", "service", "online / offline"), ("mi", "SQL Managed Instance", "database"))
           + row(2, ("files", "File shares", "storage"), ("mover", "Storage Mover / AzCopy", "service"), ("box", "Data Box", "storage", "offline"), ("azf", "Azure Files / Blob", "storage")),
           [S("problem", "Problem", "Plan done — now move it", "Each kind of workload needs its own path, and the business wants downtime measured in minutes.", add=["srv", "sql", "files"]),
            S("technique", "Workloads", "Rehost or replatform", "Azure Migrate replicates servers to Azure VMs with a test migration before cutover. Web apps can replatform to App Service with small changes.", add=["am", "vm", "aps"], edges=[("srv", "am"), ("am", "vm"), ("am", "aps")], learn=[0]),
            S("technique", "Databases", "Online keeps downtime short", "Database Migration Service copies the database and, in online mode, keeps syncing changes until you cut over. Offline is simpler but the source stops during the copy.", add=["dms", "mi"], edges=[("sql", "dms"), ("dms", "mi", "sync, then cutover")], learn=[1]),
            S("technique", "Files", "Network or ship it", "Storage Mover or AzCopy copy over the network. When the volume is huge or the link slow, Data Box ships disks to Azure. File Sync keeps branch caches afterwards.", add=["mover", "box", "azf"], edges=[("files", "mover"), ("files", "box"), ("mover", "azf"), ("box", "azf")], learn=[2]),
            S("recap", "Recap", "Migration execution", "Right tool per workload.", recap=["Azure Migrate rehost; App Service replatform", "DMS online for minimal downtime", "AzCopy / Storage Mover vs Data Box; File Sync for caches"])]),
)
qa("AZ305-4.3.3", 2, "scenario", "300 VMware VMs must move to Azure within 3 months with no code changes and a test before cutover. What do you recommend?", [("Azure Migrate agentless server migration (rehost) with test migrations", "Correct."), ("Rebuild the apps as microservices", "Far too slow."), ("Manual VHD uploads", "Error-prone at scale."), ("Azure Batch", "Not for migration.")], "a", "Azure Migrate replicates VMware VMs and supports test migration and cutover.", MIG + "tutorial-migrate-vmware")
qa("AZ305-4.3.3", 2, "scenario", "A company wants to move its VMware environment to Azure while keeping vSphere tools and without converting VMs. What do you recommend?", [("Azure VMware Solution", "Correct."), ("Azure Migrate rehost to Azure VMs", "Converts VMs to Azure VMs."), ("AKS", "Containers."), ("Azure Stack HCI", "On-premises.")], "a", "Azure VMware Solution runs VMware natively on Azure.", ML + "azure/azure-vmware/introduction")
qa("AZ305-4.3.3", 2, "scenario", "Several ASP.NET web apps on IIS should move to a managed platform with minimal code change. What do you recommend?", [("Replatform to Azure App Service using Azure Migrate web app migration", "Correct."), ("Rehost the IIS servers as VMs", "Keeps server management."), ("Rewrite as Functions", "Large change."), ("Replace with SaaS", "No SaaS equivalent.")], "a", "Azure Migrate assesses and migrates web apps to App Service.", MIG + "concepts-migration-webapps")
qa("AZ305-4.3.4", 2, "scenario", "A 2 TB production SQL Server database must move to SQL Managed Instance with no more than 15 minutes of downtime. What do you recommend?", [("Azure Database Migration Service online migration", "Correct."), ("Offline migration with backup and restore", "Downtime for the whole copy."), ("BACPAC export/import", "Slow, offline."), ("AzCopy of MDF files", "Not supported for MI.")], "a", "Online migration syncs changes until a short cutover.", ML + "azure/dms/dms-overview")
qa("AZ305-4.3.4", 3, "scenario", "Databases use cross-database queries, CLR and SQL Agent. They must move to PaaS. Which target and tool?", [("SQL Managed Instance, migrated with DMS or the Managed Instance link", "Correct."), ("SQL Database with DMS", "Those features aren't supported in SQL Database."), ("Cosmos DB with Data Factory", "Not relational SQL Server."), ("SQL Server on VMs with Data Box", "IaaS, not PaaS.")], "a", "Managed Instance supports instance-level features; DMS or MI link migrate with low downtime.", ML + "azure/azure-sql/managed-instance/managed-instance-link-feature-overview")
qa("AZ305-4.3.4", 2, "single", "Which tool checks on-premises SQL Server databases for compatibility issues with Azure SQL targets before migration?", [("Azure Migrate (SQL assessment)", "Correct."), ("Azure Advisor", "Only for Azure resources."), ("Azure Monitor", "Monitoring."), ("Storage Explorer", "Storage.")], "a", "Azure Migrate's SQL assessment reports readiness and recommended targets.", MIG + "concepts-azure-sql-assessment-calculation")
qa("AZ305-4.3.5", 2, "scenario", "600 TB of archives must move to Blob Storage. The office has a 200 Mbps link that is busy during the day. What do you recommend?", [("Azure Data Box (offline transfer)", "Correct."), ("AzCopy over the existing link", "Would take many months."), ("Azure File Sync", "Keeps caches; not bulk ingest."), ("ExpressRoute just for the copy", "Expensive and slow to provision.")], "a", "Data Box ships large volumes offline when bandwidth is limited.", ML + "azure/databox/data-box-overview")
qa("AZ305-4.3.5", 2, "scenario", "Branch offices must keep fast local access to shared files while the master copy moves to Azure. What do you recommend?", [("Azure Files with Azure File Sync caching on local servers", "Correct."), ("Data Box", "One-time transfer."), ("Blob Storage with AzCopy", "No SMB caching."), ("Azure NetApp Files", "No branch caching.")], "a", "File Sync tiers files to Azure while keeping hot files local.", ML + "azure/storage/file-sync/file-sync-introduction")
qa("AZ305-4.3.5", 2, "scenario", "50 TB of SMB and NFS shares must move to Azure Files and Blob over a good network link, managed centrally from Azure. What do you recommend?", [("Azure Storage Mover", "Correct."), ("Data Box Heavy", "Unneeded when the network is good."), ("Azure Backup", "Not migration."), ("Site Recovery", "VM replication.")], "a", "Storage Mover is the managed service for migrating file shares to Azure storage.", ML + "azure/storage-mover/service-overview")

# ================================================================ 4.4.1–4.4.2
L(
    id="az305-network-connectivity", title="Design internet and hybrid connectivity", objectives=["AZ305-4.4.1", "AZ305-4.4.2"], minutes=45,
    objective="Recommend connectivity between Azure resources and the internet (inbound and outbound) and between Azure and on-premises networks.",
    prereqs=[("Virtual networks (AZ-104)", "AZ104-4.1.1", "az104-vnet-subnets"), ("Peering (AZ-104)", "AZ104-4.1.2", "az104-vnet-peering")],
    foundation=[
        "Connectivity design answers three questions: how do users reach the app, how does the app reach the internet, and how does Azure reach the office?",
        "Inbound web traffic goes through a protected front door. Outbound traffic should leave through a known exit. Offices connect over a VPN or a private ExpressRoute line.",
    ],
    engineer=[
        "Internet inbound: Azure Front Door (global HTTP(S), WAF, caching), Application Gateway (regional HTTP(S), WAF), public Standard Load Balancer for non-HTTP, all with DDoS Protection on public IPs; Azure Firewall DNAT for controlled inbound to private services. Outbound: new VNets use private subnets (no default outbound access), so give explicit outbound with NAT gateway (static IPs, scalable SNAT), Azure Firewall (filtered egress in a hub) or load balancer outbound rules.",
        "Hybrid: site-to-site VPN (IPsec over the internet, VPN gateway active-active and zone-redundant SKUs, BGP), point-to-site VPN for users, ExpressRoute (private connection through a provider; private peering to VNets and Microsoft peering to Microsoft 365/PaaS public endpoints; Global Reach to connect sites through Microsoft's backbone; FastPath to bypass the gateway for performance; ExpressRoute Direct for 10/100 Gbps ports), ExpressRoute with site-to-site VPN as failover, and Azure Virtual WAN for large global hub-and-spoke designs with branches, VPN, ExpressRoute and secured hubs.",
        "Topology: hub-and-spoke with shared services (gateways, firewall, Bastion, DNS) in the hub and gateway transit to spokes, or Virtual WAN managed hubs; Azure Virtual Network Manager to manage connectivity and security admin rules at scale.",
    ],
    anim=("az305-net-connect-sim", "Choose internet and hybrid connectivity options."),
    example=("Connecting a manufacturer", [
        "Head office and two factories connect to the Azure hub with ExpressRoute; a site-to-site VPN is the backup path. Forty small sales offices join through Virtual WAN with SD-WAN partners.",
        "Public web apps sit behind Front Door with WAF. Spoke subnets reach the internet only through Azure Firewall in the hub, and batch VMs that call a partner API use a NAT gateway with two static IPs the partner allow-lists.",
    ]),
    config=cfg(["Virtual network gateway: VPN or ExpressRoute, SKU, active-active, zone-redundant.", "ExpressRoute circuit: provider, bandwidth, peering; connection to the gateway.", "NAT gateway: public IPs, associate with subnets.", "Virtual WAN: hubs, VPN/ExpressRoute gateways, secured hub."],
               cli="az network nat gateway create -g rg-net -n natgw-batch --public-ip-addresses pip-nat1 pip-nat2 --idle-timeout 10\naz network vnet subnet update -g rg-net --vnet-name vnet-spoke -n batch --nat-gateway natgw-batch\naz network vnet-gateway create -g rg-net -n vpngw-hub --vnet vnet-hub --gateway-type Vpn --sku VpnGw2AZ --public-ip-addresses pip-vpn1",
               ps="New-AzNatGateway -ResourceGroupName rg-net -Name natgw-batch -Location westeurope -Sku Standard -PublicIpAddress $pip1,$pip2"),
    lab=lab("Choose internet and hybrid connectivity.", [("net-connect", "connectivity option")], ["Answer every case."], ["NAT gateway for predictable outbound; ExpressRoute for private, predictable hybrid", "Virtual WAN for many branches"], ["Relying on default outbound access", "Using only VPN when the requirement says 'not over the internet'"]),
    troubleshooting=[("VMs in a new VNet can't reach the internet.", "Private subnets have no default outbound access.", "Add a NAT gateway, firewall route or public IP."),
                     ("Partner rejects calls because the source IP keeps changing.", "No defined outbound IP.", "Use a NAT gateway with static public IPs.")],
    comparisons=[("VPN vs ExpressRoute", "VPN: encrypted over the internet, quick and cheap; ExpressRoute: private, predictable, higher bandwidth and cost."), ("Hub-and-spoke vs Virtual WAN", "Self-managed hub VNets vs Microsoft-managed hubs with built-in any-to-any routing at scale.")],
    misconceptions=[("ExpressRoute traffic is encrypted by default.", "It is private but not encrypted; add MACsec (Direct) or IPsec over ExpressRoute if required."), ("VMs always have internet access.", "New VNets use private subnets by default.")],
    decisions=["Front Door/App Gateway + WAF for inbound web.", "Explicit outbound: NAT gateway or firewall.", "ExpressRoute (with VPN backup) for critical hybrid; Virtual WAN for many sites."],
    docs=[("What is NAT gateway?", NET + "nat-gateway/nat-overview"), ("About VPN Gateway", NET + "vpn-gateway/vpn-gateway-about-vpngateways"), ("What is ExpressRoute?", NET + "expressroute/expressroute-introduction"), ("What is Azure Virtual WAN?", NET + "virtual-wan/virtual-wan-about"), ("Hub-spoke network topology", AAC + "networking/architecture/hub-spoke")],
    walk_=("Let users in safely, let apps out predictably, and connect offices privately.",
           ["Inbound from the internet", "Outbound to the internet", "Hybrid: VPN, ExpressRoute, Virtual WAN"],
           row(0, ("users", "Internet users", "user"), ("fd", "Front Door + WAF", "globe"), ("app", "Web app", "compute"))
           + row(1, ("hub", "Hub VNet", "network", "firewall, gateways"), ("spoke", "Spoke VNet", "network"), ("nat", "NAT gateway", "network", "static outbound IPs"))
           + row(2, ("office", "Head office", "user"), ("er", "ExpressRoute", "network", "private"), ("vpn", "Site-to-site VPN", "network", "backup")),
           [S("problem", "Problem", "Three directions of traffic", "Customers come in from the internet, apps call partner APIs, and offices need private access to Azure.", add=["users", "app"]),
            S("technique", "Inbound", "A protected front door", "Front Door (global) or Application Gateway (regional) receives web traffic with a web application firewall. Non-web traffic uses a public load balancer. DDoS Protection guards public IPs.", add=["fd"], edges=[("users", "fd"), ("fd", "app")], learn=[0]),
            S("technique", "Outbound", "A known exit", "New subnets have no automatic internet access. A NAT gateway gives a subnet fixed public IPs for outbound calls; or route traffic through Azure Firewall in the hub to filter it.", add=["hub", "spoke", "nat"], edges=[("hub", "spoke", "peering"), ("spoke", "nat")], learn=[1]),
            S("technique", "Hybrid", "VPN, ExpressRoute, Virtual WAN", "VPN: encrypted tunnel over the internet, quick to set up. ExpressRoute: private line through a provider, predictable and fast; keep a VPN as backup. Virtual WAN: Microsoft-managed hubs for many branches and regions.", add=["office", "er", "vpn"], edges=[("office", "er"), ("office", "vpn"), ("er", "hub"), ("vpn", "hub", "failover")], learn=[2]),
            S("recap", "Recap", "Connectivity design", "In, out, and home.", recap=["Front Door / App Gateway + WAF; DDoS Protection", "NAT gateway or firewall for outbound", "VPN, ExpressRoute (+ VPN backup), Virtual WAN"])]),
)
qa("AZ305-4.4.1", 2, "scenario", "VMs in a subnet must call a partner API that only accepts two known source IPs. The VMs have no public IPs. What do you recommend?", [("A NAT gateway with two static public IPs on the subnet", "Correct."), ("Default outbound access", "Not available on private subnets and IPs aren't fixed."), ("A public IP on every VM", "More IPs and exposure."), ("ExpressRoute", "Private connectivity, not internet egress.")], "a", "NAT gateway gives predictable, scalable outbound IPs.", NET + "nat-gateway/nat-overview")
qa("AZ305-4.4.1", 2, "scenario", "A public web app in two regions needs WAF protection, global load balancing and caching. What do you recommend?", [("Azure Front Door Premium with WAF", "Correct."), ("Application Gateway in each region only", "Regional, no global routing or caching."), ("Traffic Manager only", "DNS routing without WAF or caching."), ("Public Load Balancer", "Layer 4.")], "a", "Front Door combines global routing, caching and WAF.", NET + "frontdoor/front-door-overview")
qa("AZ305-4.4.1", 3, "scenario", "All outbound internet traffic from spoke VNets must be filtered by FQDN and logged centrally. What do you recommend?", [("Azure Firewall in the hub with a 0.0.0.0/0 route from each spoke", "Correct."), ("NAT gateway in each spoke", "No FQDN filtering."), ("NSGs with service tags", "No FQDN filtering or central logging."), ("Front Door", "Inbound web traffic.")], "a", "Route spoke egress through Azure Firewall for central filtering and logging.", NET + "firewall/overview")
qa("AZ305-4.4.2", 2, "scenario", "A datacenter needs 10 Gbps to Azure with predictable latency, and traffic must not cross the public internet. What do you recommend?", [("ExpressRoute", "Correct."), ("Site-to-site VPN", "Over the internet."), ("Point-to-site VPN", "For individual devices."), ("VNet peering", "Azure-to-Azure only.")], "a", "ExpressRoute provides private, high-bandwidth connectivity.", NET + "expressroute/expressroute-introduction")
qa("AZ305-4.4.2", 2, "scenario", "The ExpressRoute circuit must have a lower-cost backup path if it fails. What do you recommend?", [("A site-to-site VPN configured as failover for ExpressRoute private peering", "Correct."), ("A second VNet", "Not a path."), ("Point-to-site VPN for every server", "Not a site backup."), ("Traffic Manager", "DNS routing.")], "a", "ExpressRoute and site-to-site VPN can coexist, with VPN as backup.", NET + "expressroute/use-s2s-vpn-as-backup-for-expressroute-privatepeering")
qa("AZ305-4.4.2", 3, "scenario", "Eighty branch offices, three regions and many VNets need any-to-any connectivity with minimal routing administration. What do you recommend?", [("Azure Virtual WAN with hubs in each region", "Correct."), ("Self-managed hub VNets with UDRs everywhere", "Heavy administration."), ("Full-mesh VNet peering only", "Doesn't connect branches."), ("Point-to-site VPN", "For users.")], "a", "Virtual WAN provides managed hubs with automatic any-to-any routing.", NET + "virtual-wan/virtual-wan-about")

# ================================================================ 4.4.3–4.4.5
L(
    id="az305-network-optimize", title="Optimise network performance and security, and choose load balancing", objectives=["AZ305-4.4.3", "AZ305-4.4.4", "AZ305-4.4.5"], minutes=45,
    objective="Recommend solutions to optimise network performance and security, and a load-balancing and routing solution.",
    prereqs=[("Load balancing (AZ-104)", "AZ104-4.3.2", "az104-load-balancer"), ("NSGs (AZ-104)", "AZ104-4.2.1", "az104-nsg-asg")],
    foundation=[
        "Fast networks keep data close (same region, zone or rack) and take short, private paths.",
        "Secure networks use layers: perimeter (DDoS, WAF), central firewall, segmentation (NSGs), and private access to services.",
        "Load balancing has a simple rule: global or regional, web or any protocol.",
    ],
    engineer=[
        "Performance: accelerated networking (SR-IOV) on supported VM sizes; proximity placement groups and same-zone placement for chatty tiers; choose regions close to users; Front Door or CDN for edge delivery; ExpressRoute (FastPath, Global Reach) for hybrid latency and throughput; Traffic Manager performance routing; VNet peering instead of gateways between VNets; private endpoints for low-latency private access.",
        "Security layers: DDoS Network Protection (or IP Protection) for public IPs; Web Application Firewall on Front Door or Application Gateway; Azure Firewall (Standard: L3–L7 rules, FQDN filtering, threat intelligence; Premium: TLS inspection, IDPS, URL filtering) in the hub; NSGs and ASGs for micro-segmentation; Azure Virtual Network Manager security admin rules for organisation-wide guardrails; Private Link and disabled public network access for PaaS; Bastion for admin access; Network Watcher and VNet flow logs for visibility; Zero Trust principles.",
        "Load balancing and routing decision: global + HTTP(S) → Front Door; global + any protocol → Traffic Manager (DNS-based) or cross-region Load Balancer; regional + HTTP(S) → Application Gateway (path routing, TLS termination, WAF) or Application Gateway for Containers; regional + TCP/UDP → Load Balancer (internal or public, HA ports for NVAs, Gateway Load Balancer for inline appliances). Combine them: Front Door → Application Gateway → internal Load Balancer.",
    ],
    anim=("az305-net-design-sim", "Choose performance features, security layers and the right load balancer."),
    example=("A secure, fast global storefront", [
        "Front Door Premium with WAF fronts the site; each region has Application Gateway routing /api and /static, and an internal Load Balancer for the order service. DDoS Network Protection covers the public IPs.",
        "Azure Firewall Premium inspects outbound TLS; spokes are segmented with NSGs and ASGs; PaaS services use private endpoints. Latency-sensitive trading VMs use accelerated networking in a proximity placement group.",
    ]),
    config=cfg(["VM > Networking > Accelerated networking; Proximity placement groups.", "Azure Firewall policy: Premium features (TLS inspection, IDPS).", "DDoS protection plan: associate with VNets.", "Front Door / Application Gateway: WAF policy."],
               cli="az network nic update -g rg-app -n nic-trade01 --accelerated-networking true\naz ppg create -g rg-app -n ppg-trading -l westeurope -t Standard\naz network ddos-protection create -g rg-net -n ddos-plan --vnets vnet-hub",
               ps="New-AzProximityPlacementGroup -ResourceGroupName rg-app -Name ppg-trading -Location westeurope -ProximityPlacementGroupType Standard"),
    lab=lab("Choose performance, security and load-balancing options.", [("net-design", "network feature"), ("lb-route", "load balancer or router")], ["Answer every case in both trainers."],
            ["PPG + accelerated networking for lowest latency", "Layered security; global vs regional, web vs any protocol"], ["Using Traffic Manager when WAF is needed", "Relying on NSGs alone for FQDN filtering"]),
    troubleshooting=[("Latency between app and database VMs is inconsistent.", "VMs placed far apart; no accelerated networking.", "Use a proximity placement group and enable accelerated networking."),
                     ("A website is hit by SQL injection attempts.", "No WAF.", "Enable WAF managed rules on Front Door or Application Gateway.")],
    comparisons=[("Azure Firewall vs NSG", "Firewall: central, stateful, FQDN and threat intelligence; NSG: distributed L3/L4 allow/deny per subnet or NIC."), ("Front Door vs Traffic Manager", "Front Door proxies HTTP(S) with WAF and caching; Traffic Manager only answers DNS.")],
    misconceptions=[("One security control is enough.", "Defence in depth: DDoS, WAF, firewall, NSGs, private access."), ("Traffic Manager sees the traffic.", "It works at DNS level; clients connect directly to endpoints.")],
    decisions=["Accelerated networking and PPGs for latency-sensitive tiers.", "Layer DDoS + WAF + Firewall + NSGs + Private Link.", "Pick the load balancer by global/regional and HTTP/any."],
    docs=[("Load-balancing options", AAC + "guide/technology-choices/load-balancing-overview"), ("Accelerated networking", NET + "virtual-network/accelerated-networking-overview"), ("Proximity placement groups", NET + "virtual-machines/co-location"), ("Azure Firewall Premium features", NET + "firewall/premium-features"), ("Azure DDoS Protection", NET + "ddos-protection/ddos-protection-overview"), ("What is Private Link?", NET + "private-link/private-link-overview")],
    walk_=("Make traffic fast and safe, and send it to the right place.",
           ["Performance: placement and accelerated networking", "Security in layers", "Choosing a load balancer"],
           row(0, ("users", "Users", "user"), ("ddos", "DDoS Protection", "security"), ("fd", "Front Door + WAF", "globe", "global, HTTP"))
           + row(1, ("agw", "Application Gateway", "network", "regional, HTTP"), ("fw", "Azure Firewall", "security", "central"), ("lb", "Load Balancer", "network", "regional, TCP/UDP"))
           + row(2, ("ppg", "Proximity placement group", "compute", "close together"), ("nsg", "NSGs + ASGs", "security"), ("pl", "Private Link", "network")),
           [S("problem", "Problem", "Slow, exposed, or both", "Trading VMs need microseconds, the website faces attacks, and traffic must reach the right backend.", add=["users"]),
            S("technique", "Fast", "Keep it close and offload work", "Proximity placement groups keep VMs physically close; accelerated networking offloads packet processing to hardware. Choose regions near users and cache at the edge.", add=["ppg"], learn=[0]),
            S("concept", "Secure", "Defence in layers", "DDoS Protection on public IPs, a web application firewall on the entry point, Azure Firewall in the hub for central filtering, NSGs and ASGs for segmentation, and Private Link so PaaS services stay off the internet.", add=["ddos", "fw", "nsg", "pl"], edges=[("users", "ddos")], learn=[1]),
            S("technique", "Route", "Two questions pick the balancer", "Global or regional? Web (HTTP/S) or any protocol? Global + web: Front Door. Regional + web: Application Gateway. Regional + any: Load Balancer. Global + any: Traffic Manager.", add=["fd", "agw", "lb"], edges=[("ddos", "fd"), ("fd", "agw"), ("agw", "lb")], learn=[2], tip="Designs often chain them: Front Door → Application Gateway → internal Load Balancer."),
            S("recap", "Recap", "Optimise the network", "Close, layered, correctly routed.", recap=["PPG + accelerated networking", "DDoS, WAF, Firewall, NSG/ASG, Private Link", "Front Door / App Gateway / Load Balancer / Traffic Manager"])]),
)
