qa("AZ305-4.4.3", 2, "scenario", "Two offices on different continents, both connected to Azure by ExpressRoute, must exchange data over Microsoft's backbone instead of the internet. What do you recommend?", [("ExpressRoute Global Reach", "Correct."), ("Site-to-site VPN between the offices", "Over the internet."), ("VNet peering", "Azure VNets only."), ("Front Door", "Web traffic.")], "a", "Global Reach links ExpressRoute circuits so sites communicate via Microsoft's network.", NET + "expressroute/expressroute-global-reach")
qa("AZ305-4.4.3", 3, "scenario", "Users worldwide complain that static content on a single-region site is slow. What is the most effective improvement?", [("Serve static content through Azure Front Door caching", "Correct."), ("Increase the App Service plan size", "Distance remains."), ("Enable accelerated networking", "VM feature, not user latency."), ("Add an internal load balancer", "Doesn't reduce distance.")], "a", "Edge caching brings content close to users.", NET + "frontdoor/front-door-caching")
qa("AZ305-4.4.4", 2, "scenario", "Outbound HTTPS traffic must be decrypted and inspected for malware and intrusion attempts. What do you recommend?", [("Azure Firewall Premium with TLS inspection and IDPS", "Correct."), ("Azure Firewall Standard", "No TLS inspection or IDPS."), ("NSG flow logs", "Logging only."), ("WAF", "Protects inbound web apps.")], "a", "Firewall Premium adds TLS inspection and signature-based IDPS.", NET + "firewall/premium-features")
qa("AZ305-4.4.4", 2, "scenario", "A public website must be protected against OWASP top 10 attacks such as SQL injection. What do you recommend?", [("Web Application Firewall on Front Door or Application Gateway", "Correct."), ("NSG rules", "Layer 4 only."), ("DDoS Protection", "Volumetric attacks."), ("Azure Bastion", "Admin access.")], "a", "WAF managed rule sets cover OWASP threats.", NET + "web-application-firewall/overview")
qa("AZ305-4.4.4", 3, "scenario", "Security requires that certain ports (for example RDP from the internet) are always denied across all VNets, even if a team adds an NSG allow rule. What do you recommend?", [("Azure Virtual Network Manager security admin rules", "Correct: evaluated before NSGs and can't be overridden by teams."), ("An NSG on every subnet", "Teams can change their NSGs."), ("Azure Policy audit only", "Doesn't block traffic."), ("Resource locks", "Don't filter traffic.")], "a", "Security admin rules enforce organisation-wide guardrails before NSG rules.", NET + "virtual-network-manager/concept-security-admins")
